package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the rates for each grade on a sheet, each in force from its from-date. */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository logs;
    private final RateVersionRepository versions;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public RateService(RateRepository rates, RateLogRepository logs, RateVersionRepository versions, SheetRepository sheets, Audit audit,
            RollupService rollup) {
        this.rates = rates;
        this.logs = logs;
        this.versions = versions;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /**
     * The sheet's rates, then each parent sheet's up to {@link RollupService#PARENT_LEVELS} levels up (nearest first),
     * each in grade order then by from-date.
     */
    public List<List<Rate>> chain(String sheetId) {
        return rollup.rateChain(sheetId);
    }

    /**
     * The grade's rate in force on the date: the one with the latest from-date on or before it, an
     * undated rate counting as from the beginning of time. Empty when the date is before every rate, or
     * after that rate's to-date. With none on the sheet, the parent sheet's, then its parent's, up to three levels up.
     */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return RollupService.rateOn(rollup.rateChain(sheetId), grade, date);
    }

    /**
     * The grade's rate percent in force on the date as the rates stood at the end of {@code asOf}: each from-date's
     * last setting made while the sheet's today was on or before it (a rate set before settings were logged counts as
     * it is now). With none on the sheet then, the parent sheets' rates in force on the date as they stood then.
     * Empty when the grade had no rate in force on the date then.
     */
    public Optional<BigDecimal> rateAsOf(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        List<Rate> stood = RateLog.stood(sheetId, grade, rates.findBySheetIdAndGrade(sheetId, grade),
                logs.findBySheetIdAndGradeOrderByIdAsc(sheetId, grade), asOf);
        Optional<BigDecimal> own = stood.stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.appliesOn(date))
                .map(Rate::getPct);
        if (own.isPresent()) {
            return own;
        }
        List<List<Rate>> chain = rollup.rateChain(sheetId, asOf);
        return RollupService.rateOn(chain.subList(1, chain.size()), grade, date).map(Rate::getPct);
    }

    /** What the grade having the percent on every date would change on the sheet; nothing is saved. */
    @Transactional(readOnly = true)
    public RollupService.RatePreview preview(String sheetId, String grade, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        return rollup.preview(sheetId, grade, pct);
    }

    /**
     * Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null: no
     * end). A rate the grade already has from the from-date is kept as an older version and the new one becomes its
     * newest, the one in force. A to-date before the from-date is refused.
     */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        if (fromDate != null && toDate != null && toDate.isBefore(fromDate)) {
            throw new RateDatesException(fromDate, toDate);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, fromDate).orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, fromDate, pct);
        } else {
            versions.save(new RateVersion(rate));
            rate.setVersion(rate.getVersion() + 1);
            rate.setPct(pct);
        }
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            throw new RateTakenException(sheetId, grade);
        }
        logs.save(new RateLog(saved, sheets.findById(sheetId).orElseThrow().getToday()));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (saved.getFromDate() == null ? "" : " from=" + saved.getFromDate())
                + (saved.getToDate() == null ? "" : " to=" + saved.getToDate()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A rate for a grade on a sheet: a percent with two decimals, in force from its from-date (or from the
 * beginning of time when it has none) until the grade's next later-dated rate, and only through its to-date
 * when it has one.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    /** The first day the rate applies; null when it applies from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The last day the rate applies; null when it applies until the grade's next later-dated rate. */
    @Column(name = "to_date")
    private LocalDate toDate;

    /** How many versions the rate has had; this one, the newest, is the one in force. */
    @Column(name = "version", nullable = false)
    private int version = 1;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }

    public int getVersion() {
        return version;
    }

    public void setVersion(int version) {
        this.version = version;
    }

    /** Whether the rate applies on the date, given it is the grade's latest-dated rate on or before it. */
    public boolean appliesOn(LocalDate date) {
        return toDate == null || !date.isAfter(toDate);
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** The rates for each grade on a sheet, each from its from-date. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * A rate as shown: the percent with two decimals, and its from- and to-dates as yyyy-mm-dd (null when it has none);
     * how many versions it has had (the one shown being the newest, in force); and its level, 0 for the sheet's own, 1 for its parent sheet's, 2 for that sheet's parent's and so on.
     */
    public record RateView(String grade, String pct, String from, String to, int version, int level) {

        static RateView of(Rate rate) {
            return of(rate, 0);
        }

        static RateView of(Rate rate, int level) {
            return new RateView(rate.getGrade(), rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    rate.getFromDate() == null ? null : rate.getFromDate().toString(),
                    rate.getToDate() == null ? null : rate.getToDate().toString(), rate.getVersion(), level);
        }
    }

    /**
     * A percent of 0.00 up to 999.99 with up to two decimals, and an optional from-date as yyyy-mm-dd;
     * a blank or missing from-date means the rate applies from the beginning of time. An optional to-date likewise:
     * blank or missing means the rate has no end.
     */
    public record RateRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String pct,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String to) {

        BigDecimal pctValue() {
            return new BigDecimal(pct.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }

        LocalDate fromValue() {
            return date(from);
        }

        LocalDate toValue() {
            return date(to);
        }

        private static LocalDate date(String value) {
            if (value == null || value.isBlank()) {
                return null;
            }
            try {
                return LocalDate.parse(value.trim());
            } catch (DateTimeParseException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + value.trim());
            }
        }
    }

    /** Lines of grade,rate,from,to to set as rates. */
    public record ImportRequest(@NotNull @Size(max = 1000000) String text) {
    }

    /** How many rates an import set. */
    public record ImportResult(int set) {
    }

    private final RateService service;
    private final ImportRatesService imports;

    public RateController(RateService service, ImportRatesService imports) {
        this.service = service;
        this.imports = imports;
    }

    /**
     * The sheet's rates in grade order, then by from-date (the undated one first); a grade with no rate is left out.
     * Then, likewise, the rates of its parent sheet, of that sheet's parent and so on up to three levels up, each
     * with its level.
     */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        List<List<Rate>> chain = service.chain(sheetId.trim());
        List<RateView> views = new ArrayList<>();
        for (int level = 0; level < chain.size(); level++) {
            for (Rate rate : chain.get(level)) {
                views.add(RateView.of(rate, level));
            }
        }
        return views;
    }

    /**
     * What setting the grade's rate to the percent on every date would change, saving nothing: how many OPEN and PENDING
     * claims would show a different due, and the sum of the differences.
     */
    @GetMapping("/preview")
    public RollupService.RatePreview preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String pct,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.preview(sheetId.trim(), grade, new BigDecimal(pct.trim()).setScale(2, RoundingMode.UNNECESSARY));
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RateRequest request) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, request.fromValue(),
                request.toValue(), request.pctValue()));
    }

    /** Set a rate per pasted line, in order, each as the rate form would; refused as a whole when any line is. */
    @PostMapping("/import")
    public ImportResult importRates(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ImportRequest request) {
        return new ImportResult(imports.importRates(sheetId.trim(), user.trim(), request.text()));
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** A sheet's rates in grade order, each grade's undated rate first and then by from-date. */
    List<Rate> findBySheetIdOrderByGradeAscFromDateAscIdAsc(String sheetId);

    /** A grade's rates on a sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate with the from-date, or its undated rate when {@code fromDate} is null. */
    Optional<Rate> findBySheetIdAndGradeAndFromDate(String sheetId, String grade, LocalDate fromDate);
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** An older version of a rate: the percent and to-date it had before a later setting replaced them. */
@Entity
@Table(name = "rate_version")
public class RateVersion {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "rate_id", nullable = false)
    private Long rateId;

    @Column(name = "version", nullable = false)
    private int version;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected RateVersion() {
    }

    /** The rate as it stands now, kept as an older version. */
    public RateVersion(Rate rate) {
        this(rate.getId(), rate.getVersion(), rate.getPct(), rate.getToDate());
    }

    private RateVersion(Long rateId, int version, BigDecimal pct, LocalDate toDate) {
        this.rateId = rateId;
        this.version = version;
        this.pct = pct;
        this.toDate = toDate;
    }

    /** A copy of the version for another rate. */
    public RateVersion copyTo(Long rateId) {
        return new RateVersion(rateId, version, pct, toDate);
    }

