    @Transactional
    public int importRates(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        String[] rows = text.split("\\r?\\n");
        for (int i = 0; i < rows.length; i++) {
            if (!rows[i].isBlank()) {
                lines.add(parse(i + 1, rows[i]));
